// hyperbolic halfplane distance
float hyperDist(vec2 u, vec2 v){

    return 4.*pow(length(u-v),2.)/(2.-pow(length(u),2.))/(2.-pow(length(v),2.)); 
}


// noise function vec2->vec2
vec2 noise22(vec2 uv){

    vec3 a = fract(uv.xyx*vec3(123.34, 234.34, 345.65));
    a += dot(a, a + 34.45);

    return fract(vec2(a.x * a.y, a.y * a.z));
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // normalize pixel coordinates 
    vec2 uv = 2.8*( fragCoord -.5*iResolution.xy ) / iResolution.y;

    // time
    float t = 0.3*iTime+100.;

    // draw n randomly positioned points
    float m = 0., 
          n = 80.,
          minDist = 4.,
          cellIndex = 0.;

    for(float i=0.; i<n; i++){

        vec2 r = noise22(vec2(i+2.)),
             p = sin(r*t);

        float d = hyperDist(uv, p);

        // find minimal distance to a particular point
        if(d<minDist){
            minDist = d;
            cellIndex =i;
        }
    }

    //black outside the circle
    float col = 0.;
    if(length(uv) < 1.25)  col = 0.8*+minDist;

    // output to screen
    fragColor = vec4(col);
}
